<?php
declare(strict_types=1);require_once __DIR__.'/../app/bootstrap.php';use BAJAMA\Core\Auth;use BAJAMA\Core\License;use BAJAMA\Core\RBAC;use BAJAMA\Core\Tenant;use BAJAMA\Network\MikroTik;use BAJAMA\Network\RouterOsLiveData;Auth::requireLogin();$db=db();License::requireFeature($db,'mikrotik');RBAC::require($db,'mikrotik.view');$org=(int)Tenant::id();$routers=MikroTik::all($db,$org);$routerId=(int)($_GET['router_id']??($routers[0]['id']??0));$rows=[];$error='';try{if($routerId>0)$rows=RouterOsLiveData::read($db,$org,$routerId)['addresses'];}catch(Throwable $e){$error=$e->getMessage();}function si_h($v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}$pageTitle='Static IP Aktif';ob_start();?><meta http-equiv="refresh" content="30"><div class="container-fluid py-4"><h1 class="fw-bold">Static IP Aktif</h1><p class="text-muted">Address aktif dibaca langsung dari MikroTik. Address dynamic disaring.</p><?php if($error):?><div class="alert alert-danger"><?=si_h($error)?></div><?php endif;?><form class="mb-3"><select name="router_id" class="form-select" onchange="this.form.submit()"><?php foreach($routers as $r):?><option value="<?=$r['id']?>" <?=$routerId==(int)$r['id']?'selected':''?>><?=si_h($r['name'])?></option><?php endforeach;?></select></form><div class="card border-0 shadow-sm"><div class="table-responsive"><table class="table table-hover mb-0"><thead><tr><th>Address</th><th>Interface</th><th>Network</th><th>Comment</th></tr></thead><tbody><?php foreach($rows as $r):?><?php if(strtolower((string)($r['dynamic']??'no'))==='yes')continue;?><tr><td><?=si_h($r['address']??'')?></td><td><?=si_h($r['interface']??'')?></td><td><?=si_h($r['network']??'')?></td><td><?=si_h($r['comment']??'')?></td></tr><?php endforeach;?></tbody></table></div></div></div><?php $content=ob_get_clean();require __DIR__.'/../app/layout/layout.php';
